import {escapeHTML as e} from '../../shared/primitives.js';
import {avatar,icon,pageHeading,empty} from '../../shared/ui.js';
const locationName=(c,id)=>c.locations.find(l=>l.id===id)?.name||'Local desconhecido';
const button=(action,label,primary=false)=>`<button class="${primary?'primary':''}" data-action="${action}">${icon('plus')}${label}</button>`;
export function characterView(c,query='',regionFilter='',spatial) {
 const label=id=>spatial?.regionLabel(c,id)||c.regions.find(r=>r.id===id)?.name||'Sem região definida';
 const q=query.toLocaleLowerCase('pt-BR');const chars=c.characters.filter(ch=>(!regionFilter||(regionFilter==='unknown'?!ch.regionId:(spatial?spatial.belongsToRegion(c,ch,regionFilter):ch.regionId===regionFilter)))&&[ch.name,ch.role,ch.faction,locationName(c,ch.locationId),ch.summary,label(ch.regionId)].join(' ').toLocaleLowerCase('pt-BR').includes(q));
 return `${pageHeading('ROSTOS, ESCOLHAS E VÍNCULOS','Personagens','Fichas vivas para quem habita o seu mundo.',button('new-character','Novo personagem',true))}<div class="list-toolbar"><label class="search-box">${icon('search')}<input id="filter" type="search" placeholder="Buscar nome, função, facção ou local…" value="${e(query)}" aria-label="Buscar personagens"></label><label class="region-filter"><span class="sr-only">Filtrar por região</span><select id="region-filter" aria-label="Filtrar por região"><option value="">Todas as regiões</option>${c.regions.map(r=>`<option value="${e(r.id)}" ${regionFilter===r.id?'selected':''}>${e(label(r.id))}</option>`).join('')}<option value="unknown" ${regionFilter==='unknown'?'selected':''}>Sem região definida</option></select></label><span class="muted">${chars.length} personagens</span></div><div class="character-grid">${chars.map(ch=>`<article class="character-card"><button class="character-cover" data-open-character="${e(ch.id)}">${avatar(ch,'card-portrait')}<span class="card-rank">${e(ch.rank)}</span></button><div class="card-content"><small>${e(ch.role)}</small><h2><button class="text-button" data-open-character="${e(ch.id)}">${e(ch.name)}</button></h2><p class="location-line">${icon('pin')}${e(locationName(c,ch.locationId))}</p><p class="character-region">${e(label(ch.regionId))}</p><p class="card-summary">${e(ch.summary)}</p><div class="card-footer"><span>${e(ch.faction)}</span><button class="text-button" data-edit-character="${e(ch.id)}">Editar ↗</button></div></div></article>`).join('')}</div>${chars.length?'':empty('Nenhum personagem encontrado','Tente outra busca ou adicione um novo integrante.')}`;
}
